'use strict';

window.PhoenixNearbyModel={
 state(id,{tasks,engine,state}){const quest=!!tasks[id]?.stages,complete=quest?engine.done(id,state.progress):state.completed[id]===true,status=quest?engine.status(id,state.progress):'',availability=engine.availability(id,state.progress);return {complete,missed:!complete&&status==='failed',unknown:!complete&&(availability==='unknown'||status==='unavailable'),blocked:!complete&&availability==='blocked',status,availability};},
 counts(ids,context){const states=ids.map(id=>this.state(id,context));return {total:states.length,unfinished:states.filter(s=>!s.complete&&!s.missed).length,allCompleted:states.length>0&&states.every(s=>s.complete)};},
 prerequisite(id,tasks){if(id==='q-beast')return {text:'Question the garrison commander first.',href:'#'+tasks['q-lilac'].view+'/3'};if(id==='q-incident')return {text:'Complete the griffin contract first.',href:'#'+tasks['q-beast'].view+'/payment'};return null;},
 routeOrder(ids,context){return ids.map((id,index)=>({id,index,missed:this.state(id,context).missed})).sort((a,b)=>Number(a.missed)-Number(b.missed)||a.index-b.index).map(x=>x.id);}
};

window.createPhoenixQuestHubs=function({state,tasks,hubs,engine,navigate}){
 const make=(tag,text,cls)=>{const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e;};
 const link=(text,href,cls)=>{const e=make('a',text,cls);e.href=href;return e;};
 const primary=h=>h.items.find(id=>tasks[id].home===h.id&&window.PHOENIX_PROGRESS_DATA.quests[id]);
 const root=document.getElementById('whiteorchard-tree'),models=new Map();
 function artwork(id){if(window.PHOENIX_DIAGRAM_ART[id])return window.PHOENIX_DIAGRAM_ART[id];if(window.PHOENIX_EXPLORATION_ART[id])return window.PHOENIX_EXPLORATION_ART[id];if(tasks[id].stages)return {src:'art-r13/'+id+'-card.webp',focus:'50% 30%'};const marker=window.PHOENIX_MAP.markers.find(p=>p.task===id);return {src:marker?.type==='service'?'gwent-r15/gabor.webp':tasks[id].category==='preparation'?'art-white-orchard-variety/category-preparation.webp':'art-white-orchard-illustrated/category-discoveries.webp',focus:'50% 30%'};}
 function groupFor(id){const t=tasks[id];if(t.diagram)return 'Diagrams';if(t.stages)return 'Quests & contracts';if(window.PHOENIX_MAP.markers.some(p=>p.task===id&&p.type==='service'))return 'Merchants & services';if(t.category==='preparation'||window.PHOENIX_EXPLORATION.details[id]?.category==='preparation')return 'Preparation';return 'Exploration';}
 function destination(id){const t=tasks[id];if(t.stages)return '#whiteorchard-tree/'+t.home+'/'+id;const service=window.PHOENIX_MAP.markers.find(p=>p.task===id&&p.type==='service');return service?'#economy-merchants/'+service.id:'#'+t.view;}
 function rail(host,label){const list=make('nav',null,'quest-hub-rail');list.setAttribute('aria-label',label);list.tabIndex=0;const controls=make('div',null,'quest-hub-rail-controls'),prev=make('button','←'),next=make('button','→');prev.type=next.type='button';prev.setAttribute('aria-label','Previous '+label);next.setAttribute('aria-label','Next '+label);prev.onclick=()=>list.scrollBy({left:-220,behavior:'auto'});next.onclick=()=>list.scrollBy({left:220,behavior:'auto'});controls.append(prev,make('span','Swipe to browse'),next);host.append(list,controls);return list;}
 for(const h of hubs){const q=primary(h);if(!q)continue;const task=tasks[q],panel=document.getElementById(h.id+'-activities'),legacy=make('div',null,'quest-hub-legacy');legacy.hidden=true;legacy.append(...panel.children);panel.append(legacy);panel.classList.add('quest-hub-panel');
  const header=make('header',null,'quest-hub-briefing'),im=make('img');im.src='art-r13/'+q+'-card.webp';im.alt='';im.loading='lazy';header.append(im,make('p','WHITE ORCHARD · '+(Number.isFinite(task.level)?'SUGGESTED LEVEL '+task.level:'QUEST BRIEFING'),'eyebrow'),make('h1',task.name));
  const description=make('p',task.intro,'quest-hub-description'),warning=make('p',null,'quest-hub-risk'),resume=link('', '#'+task.view,'home-action-tile'),resumeTitle=make('strong'),resumeStep=make('small'),resumeLabel=make('span'),resumeArt=make('img');resumeArt.src='navigation-art-v26/action-walkthrough.webp';resumeArt.alt='';resumeArt.loading='lazy';resumeLabel.append(resumeTitle,resumeStep);resume.append(resumeArt,resumeLabel);
  const tools=make('nav',null,'quest-hub-tools');tools.setAttribute('aria-label',task.name+' hub tools');const map=link('','#whiteorchard-map/cluster/'+h.id+'/'+q,'home-action-tile'),mapArt=make('img');mapArt.src='white-orchard-map.webp';mapArt.alt='';mapArt.loading='lazy';map.append(mapArt,make('span','Map'));tools.append(map,link('Quest cards','#whiteorchard-tree','quest-cards-return'),link('Region','#whiteorchard-console'));
  tools.querySelector('.quest-cards-return').onclick=e=>{e.preventDefault();e.stopPropagation();navigate('#whiteorchard-tree',{tree:{selectedHub:h.id,expandedHub:null,windowStart:h.group,scrollY:0,scrollX:0,groupOpen:{...state.groupOpen}}});};
  const progress=make('div',null,'quest-hub-progress'),nearby=make('section',null,'quest-hub-nearby');nearby.append(make('h2','Nearby activities'));
  const done=make('details',null,'quest-hub-completed');done.hidden=true;done.append(make('summary','Completed'));const doneRail=rail(done,'completed nearby activities'),emptyDone=make('p','No completed nearby activities recorded.');done.append(emptyDone);
  const paper=make('article',null,'quest-hub-paper'),preparation=make('div',null,'quest-hub-preparation');paper.append(description,warning,resume,tools,preparation,progress);panel.prepend(header,paper,nearby,done);
  const groups=new Map(),cards=new Map(),ids=[...new Set([...(window.PHOENIX_MAP_MEMBERSHIP[h.id]||[]),...h.items])].filter(id=>id!==q&&tasks[id]);
  for(const id of ids){const label=groupFor(id);let group=groups.get(label);if(!group){const section=make('section',null,'quest-hub-group');section.append(make('h3',label));group={section,rail:rail(section,label.toLowerCase())};groups.set(label,group);nearby.append(section);}const a=link('',destination(id),'quest-hub-card'),art=artwork(id),image=make('img');image.src=art.src;image.alt='';image.loading='lazy';image.style.objectPosition=art.focus;const status=make('small');a.dataset.nearbyTask=id;a.dataset.originHub=h.id;a.append(image,make('strong',tasks[id].name),status);const wrap=make('article',null,'nearby-card-entry'),context=make('p',null,'nearby-card-context'),other=make('details',null,'nearby-other-stops'),prerequisite=make('p',null,'nearby-prerequisite'),check=make('p',null,'nearby-verification');other.append(make('summary','Other quest stops'));for(const related of hubs.filter(x=>x.id!==h.id&&(window.PHOENIX_MAP_MEMBERSHIP[x.id]||x.items).includes(id)))other.append(link(related.name,'#whiteorchard-tree/'+related.id+'/'+id));other.hidden=other.children.length===1;const approach=window.PHOENIX_EXPLORATION.details[id]?.approach||'';const fitting=task.stages.find(stage=>stage.detours?.some(d=>d.task===id));context.textContent=(fitting?'Fits '+fitting.title.toLowerCase()+'. ':'On the suggested nearby route for '+task.name+'. ')+(approach?approach.split(/(?<=\.)\s/)[0]:tasks[id].why||'Open the shared entry for location and instructions.');wrap.append(a,context,prerequisite,check,other);group.rail.append(wrap);cards.set(id,{a,status,group,wrap,prerequisite,check});}
  for(const label of ['Quests & contracts','Diagrams','Exploration','Preparation','Merchants & services'])if(groups.has(label))nearby.append(groups.get(label).section);
  const empty=make('p','No nearby activities in this cluster.');nearby.append(empty);models.set(h.id,{h,q,panel,warning,resume,resumeTitle,resumeStep,progress,preparation,nearby,done,doneRail,emptyDone,empty,groups,cards});
 }
 function refresh(restore=false){const pieces=location.hash.slice(1).split('/'),active=pieces[0]==='whiteorchard-tree'&&models.has(pieces[1]);root.classList.toggle('quest-hub-mode',active);document.body.classList.toggle('reading-hub',active);document.getElementById('tree-title').textContent=active?tasks[models.get(pieces[1]).q].name:'White Orchard · Quest journal';
  for(const m of models.values()){const t=tasks[m.q],saved=t.stages.find(s=>s.id===state.stageByView[t.view]),first=t.stages[0];m.resume.href='#'+t.view+'/'+(saved||first).id;m.resumeTitle.textContent=saved?'Continue walkthrough':'Start walkthrough';m.resumeStep.textContent=(saved||first).title;const v=window.PhoenixHomePanel.selectedQuestView(m.q,engine,state.progress,tasks);const early=t.startWarning,earlyText=early&&(!early.activity||!state.completed[early.activity])&&!engine.done(early.untilQuest,state.progress)?early.text:'';m.warning.hidden=!earlyText&&!v?.warning;m.warning.textContent=earlyText||(window.PHOENIX_PROGRESS_DATA.riskQuests.includes(m.q)&&!['complete','failed','unavailable'].includes(v?.status)?'Finish before leaving White Orchard.'+(v.status==='not started'?' Not recorded — check in game.':''):v?.warning||'');
   const context={tasks,engine,state};
   for(const [id,c]of m.cards){const info=window.PhoenixNearbyModel.state(id,context);c.a.hidden=false;c.a.classList.toggle('is-complete',info.complete);c.status.textContent=info.complete?'✓ Completed':info.missed?'Recorded failed':info.blocked?'Prerequisite needed':info.unknown?'Availability unconfirmed':'Open entry';c.prerequisite.replaceChildren();const required=window.PhoenixNearbyModel.prerequisite(id,tasks);c.prerequisite.hidden=!required||info.complete;if(required&&!info.complete)c.prerequisite.append(link(required.text,required.href));c.check.hidden=!info.unknown||info.complete;if(info.unknown&&!info.complete)c.check.textContent=info.status==='unavailable'?'Recorded story progress cannot confirm the in-game outcome. Check your quest journal.':'Your guide records do not confirm availability. Check this activity or quest in game; the shared entry explains its location.';}
   for(const [label,g]of m.groups){const ids=[...m.cards].filter(([id,c])=>c.group===g).map(([id])=>id);for(const id of window.PhoenixNearbyModel.routeOrder(ids,context))g.rail.append(m.cards.get(id).wrap);g.section.hidden=!ids.length;}m.empty.hidden=[...m.groups.values()].some(g=>!g.section.hidden);m.done.hidden=true;
  }
  const restored=restore?history.state?.tree?.hubDecks:null;if(active&&restored){const m=models.get(pieces[1]);m.done.open=restored.completed===true;requestAnimationFrame(()=>{for(const [name,g]of m.groups)if(Number.isFinite(restored.rails?.[name]))g.rail.scrollLeft=restored.rails[name];m.doneRail.scrollLeft=restored.doneX||0;});}
  return active?models.get(pieces[1]):null;
 }
 const api={models,refresh,capture(){const m=models.get(location.hash.split('/')[1]);return m?{completed:m.done.open,rails:Object.fromEntries([...m.groups].map(([name,g])=>[name,g.rail.scrollLeft])),doneX:m.doneRail.scrollLeft}:null;}};
 window.PhoenixQuestHubs=api;return api;
};
